import React, { useState, useEffect } from 'react';
import type { Meta, StoryObj } from "@storybook/nextjs";
import { Skeleton } from "./Skeleton";
import { Box, Flex, Text, Avatar, Button } from "../index";

const meta: Meta<typeof Skeleton> = {
  title: "Design System/Atoms/Skeleton",
  component: Skeleton,
  parameters: {
    docs: {
      description: {
        component: `A skeleton loading component for displaying placeholder content while data is being fetched. Creates a pulsing animation effect to indicate loading state and maintain layout structure during async operations.

**Features:**
- Smooth pulse animation (1.5s infinite loop)
- Three preset variants: title, text, circle
- Fully customizable via css prop for width, height, border-radius
- Consistent styling with design system tokens

**Accessibility:**
- Use \`aria-busy="true"\` on parent containers during loading
- Consider adding \`aria-label="Loading"\` or similar for screen readers
- Maintain semantic HTML structure even with skeletons
- Ensure skeletons match the approximate size/shape of final content

**Best practices:**
- Use skeletons that match the shape and size of actual content
- Combine multiple skeletons to create realistic loading states
- Keep skeleton hierarchy similar to final content hierarchy
- Avoid excessive skeleton complexity - simpler is better
- Consider showing partial content + skeletons for progressive loading`,
      },
    },
  },
  argTypes: {
    variant: {
      control: { type: 'select' },
      options: ['title', 'text', 'circle', undefined],
      description: 'Preset skeleton variant',
      table: {
        type: { summary: '"title" | "text" | "circle"' },
      },
    },
    css: {
      control: 'object',
      description: 'Custom Stitches CSS styling (width, height, borderRadius, etc.)',
      table: {
        type: { summary: 'CSS' },
      },
    },
  },
};

export default meta;
