// Before and after loading
export const BeforeAndAfter: Story = {
  render: () => {
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
      const timer = setTimeout(() => setIsLoading(false), 3000);
      return () => clearTimeout(timer);
    }, []);

    return (
      <Box css={{ p: '$lg', maxWidth: '400px' }}>
        <Flex css={{ flexDirection: 'column', gap: '$lg' }}>
          <Button onClick={() => setIsLoading(!isLoading)} color="secondary">
            {isLoading ? 'Stop Loading' : 'Start Loading'}
          </Button>

          <Box
            css={{
              padding: '$lg',
              border: '1px solid $bg04',
              borderRadius: '$2',
              backgroundColor: '$bg02',
            }}
          >
            {isLoading ? (
              <Flex css={{ flexDirection: 'column', gap: '$md' }}>
                <Flex css={{ gap: '$md', alignItems: 'center' }}>
                  <Box css={{ width: '48px', height: '48px' }}>
                    <Skeleton variant="circle" />
                  </Box>
                  <Flex css={{ flexDirection: 'column', gap: '$xs', flex: 1 }}>
                    <Skeleton variant="title" css={{ width: '60%' }} />
                    <Skeleton variant="text" css={{ width: '40%' }} />
                  </Flex>
                </Flex>
                <Skeleton variant="text" />
                <Skeleton variant="text" css={{ width: '90%' }} />
                <Skeleton variant="text" css={{ width: '70%' }} />
              </Flex>
            ) : (
              <Flex css={{ flexDirection: 'column', gap: '$md' }}>
                <Flex css={{ gap: '$md', alignItems: 'center' }}>
                  <Avatar
                    src="/assets/badge.svg"
                    size={48}
                  />
                  <Flex css={{ flexDirection: 'column' }}>
                    <Text variant="h5">John Doe</Text>
                    <Text variant="metadata" css={{ color: '$textMiddle' }}>
                      @johndoe
                    </Text>
                  </Flex>
                </Flex>
                <Text>
                  This is the actual content that appears after loading completes.
                  Notice how the skeleton matches the final content structure.
                </Text>
              </Flex>
            )}
          </Box>
        </Flex>
      </Box>
    );
  },
  parameters: {
    docs: {
      description: {
        story: 'Interactive demo showing transition from skeleton loading state to actual content. Automatically loads after 3 seconds, or use button to toggle.',
      },
    },
  },
};
